<?php require 'includes/core.php';$u=require_logged_in();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM notifications WHERE id=? AND user_id=?');$s->execute([$id,$u['id']]);$n=$s->fetch();if(!$n){http_response_code(404);exit('Notificação não encontrada');}db()->prepare('UPDATE notifications SET read_at=NOW() WHERE id=? AND user_id=?')->execute([$id,$u['id']]);$dest=$n['link_url'];if(!preg_match('~^(?:admin/ticket\.php\?id=[0-9]+|user/ticket\.php\?id=[0-9]+|admin/users\.php|admin/dashboard\.php|user/dashboard\.php|plans\.php)$~',$dest))$dest='notifications.php';if($u['role']==='admin' && !str_starts_with($dest,'admin/'))$dest='notifications.php';if($u['role']!=='admin' && !str_starts_with($dest,'user/'))$dest='notifications.php';go($dest);